sys_atf_step.step_config:
{"script": "(function(outputs, steps, stepResult, assertEqual) {
 var lista = new ReferenceCacheService().getServicos();
 var encontrado = lista.some(function(s) { return s.nome === 'Servico Renomeado ATF'; });
 assertEqual({ name: 'cache atualizado após alteração', shouldbe: true, value: encontrado });
})(outputs, steps, stepResult, assertEqual);"}
